krb5_error_code find_alternate_tgs(
    kdc_realm_t *kdc_active_realm,
    krb5_principal princ,
    krb5_db_entry **server_ptr,
    const char **status) {
    krb5_error_code code = KRB5_KDC_ERR_NONE;
    krb5_db_entry *server = NULL;
    kdc_realm_t *current_realm = NULL;
    krb5_boolean is_cross_tgs = FALSE;

    /* Ensure the principal is a cross TGS principal */
    if (!krb5_is_kdc_principal(princ)) {
        *status = "Provided principal is not a cross TGS principal.";
        return KRB5KDC_ERR_WRONG_REALM;
    }

    current_realm = kdc_active_realm;
    while (current_realm != NULL) {
        krb5_db_entry *candidate = NULL;

        /* Retrieve candidate TGS server */
        code = get_tgs_server_entry(current_realm, &candidate);
        if (code != KRB5_KDC_ERR_NONE) {
            current_realm = current_realm->next_realm;
            continue;
        }

        /* Skip the first entry as it's the primary TGS */
        if (!server) {
            server = candidate;
            current_realm = current_realm->next_realm;
            continue;
        }

        /* Check if candidate is available and suitable */
        if (candidate && is_server_available(candidate)) {
            server = candidate;
            break;
        }

        current_realm = current_realm->next_realm;
    }

    if (!server) {
        *status = "No suitable alternate TGS found.";
        return KRB5_KDC_ERR_SVC_UNAVAILABLE;
    }

    *server_ptr = server;
    *status = "Alternate TGS found successfully.";
    return KRB5_KDC_ERR_NONE;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code ret = KRB5_KDC_INVALID_SVC;
    krb5_db_entry *server = NULL;
    krb5_principal tgs_princ = NULL;

    assert(krb5_is_kdc_principal(princ)); // Principal must be a cross TGS

    // Walk the realm tree to find potential TGS servers
    for (kdc_realm_t *realm = kdc_active_realm; realm != NULL; realm = realm->next) {
        // Skip the first TGS entry in the realm
        if (realm->tgs_principal && realm->tgs_entry && realm != kdc_active_realm->parent_realm) {
            server = realm->tgs_entry;
            ret = KRB5_OK;
            break;
        }
    }

    if (server) {
        *server_ptr = server;
        *status = "Alternate TGS found successfully.";
    } else {
        *server_ptr = NULL;
        *status = "No suitable alternate TGS found.";
        ret = KRB5_KDC_NO_TGS;
    }

    return ret;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code code = KRB5KDC_NO_TGS_FOUND;
    krb5_db_entry *server = NULL;
    *server_ptr = NULL;
    *status = NULL;

    if (!princ || !krb5_is_kdc_principal(princ)) {
        *status = "Principal is not a cross TGS principal.";
        return KRB5KDC_BAD_PRINCIPAL;
    }

    kdc_realm_t *realm = kdc_active_realm;
    while (realm) {
        for (int i = 1; i < realm->tgs_servers->len; ++i) {  // Skip first entry
            server = g_array_index(realm->tgs_servers, krb5_db_entry *, i);
            if (server && is_tgs_available(server)) {
                *server_ptr = server;
                code = 0;
                *status = "Alternate TGS found.";
                return code;
            }
        }
        realm = realm->next;
    }

    *status = "No alternate TGS found.";
    return code;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code retval = KRB5_KDC_NO_TGS;
    krb5_db_entry *server = NULL;
    krb5_principal tgs_princ = NULL;
    int found = 0;

    assert(krb5_is_kdc_principal(princ));

    *server_ptr = NULL;

    for (kdc_realm_t *realm = kdc_active_realm; realm != NULL; realm = realm->parent_realm) {
        tgs_princ = krb5_build_principal(NULL, realm->realm, 0, NULL);
        if (!tgs_princ) {
            *status = "Failed to build TGS principal.";
            return ENOMEM;
        }

        server = krb5_db_get_principal(tgs_princ, 0, NULL);
        if (server && server->princ != NULL && server->princ != princ) {
            *server_ptr = server;
            *status = "Alternate TGS found.";
            found = 1;
            break;
        }

        if (tgs_princ) {
            krb5_free_principal(tgs_princ);
        }

        if (server) {
            krb5_db_free_principal(server);
        }
    }

    if (!found) {
        *status = "No suitable alternate TGS found.";
        if (server) {
            krb5_db_free_principal(server);
        }
    }

    return found ? 0 : KRB5_KDC_NO_TGS;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code ret = KRB5KDC_NO_TGS_FOUND;
    krb5_db_entry *tgs_entry = NULL;
    kdc_realm_t *current_realm = NULL;

    *server_ptr = NULL;
    *status = NULL;

    if (!princ || !krb5_is_krbtgt_principal(princ)) {
        *status = "Principal is not a cross TGS principal.";
        return KRB5KDC_BAD_PRINCIPAL;
    }

    for (current_realm = kdc_active_realm->next; current_realm != NULL; current_realm = current_realm->next) {
        ret = kdc_find_tgs(current_realm, princ, &tgs_entry);
        if (ret == 0 && tgs_entry != NULL) {
            *server_ptr = tgs_entry;
            *status = "Alternate TGS found.";
            return 0;
        }
    }

    *status = "No suitable alternate TGS found.";
    return ret;
}
